// ── Finding photos for an exercise by name (plans saved before this update) ──

/** FITORA's original plan exercises → their library exercise (older saved plans use these names). */
export const PLAN_NAME_TO_ID: Record<string, string> = {
  'barbell bench press': 'Barbell_Bench_Press_-_Medium_Grip',
  'seated dumbbell press': 'Seated_Dumbbell_Press',
  'cable tricep pushdowns': 'Triceps_Pushdown',
  'incline dumbbell flyes': 'Incline_Dumbbell_Flyes',
  'dumbbell lateral raises': 'Side_Lateral_Raise',
  'parallel bar dips': 'Dips_-_Chest_Version',
  'lat pulldown': 'Wide-Grip_Lat_Pulldown',
  'single-arm dumbbell row': 'One-Arm_Dumbbell_Row',
  'incline dumbbell bicep curl': 'Incline_Dumbbell_Curl',
  'full body foam rolling & mobility': 'Quadriceps-SMR',
  'barbell back squat': 'Barbell_Squat',
  'romanian deadlift (rdl)': 'Romanian_Deadlift',
  'standing calf raises': 'Standing_Calf_Raises',
  'overhead barbell military press': 'Standing_Military_Press',
  'hanging leg raises': 'Hanging_Leg_Raise',
  'hiit interval rowing or sprints': 'Rowing_Stationary',
  'standard push-ups': 'Pushups',
  'push-ups': 'Pushups',
};

const STOP_WORDS = new Set(['the', 'and', 'or', 'with', 'a', 'full', 'body', 'hiit', 'interval', 'standard', 'regular', 'classic', 'flat']);

const words = (s: string) =>
  s
    .toLowerCase()
    .replace(/\(.*?\)/g, ' ')
    .replace(/\b(push|pull|sit|chin|step)[\s-]+ups?\b/g, '$1up')
    .replace(/[^a-z0-9 ]+/g, ' ')
    .split(' ')
    .map((w) => w.replace(/ies$/, 'y').replace(/s$/, ''))
    .filter((w) => w && !STOP_WORDS.has(w));

/** Best library match for a free-text exercise name, or null when nothing is close. */
export function findExerciseByName(db: DbExercise[], name: string): DbExercise | null {
  const known = PLAN_NAME_TO_ID[name.trim().toLowerCase()];
  if (known) {
    const ex = db.find((e) => e.id === known);
    if (ex) return ex;
  }
  const target = words(name);
  if (!target.length) return null;
  let best: DbExercise | null = null;
  let bestScore = 0;
  for (const ex of db) {
    const w = words(ex.name);
    const hits = target.filter((t) => w.includes(t)).length;
    // Reward covering the requested words; extra words in the candidate (variants) cost more
    const score = hits / target.length - (w.length - hits) * 0.1;
    if (score > bestScore || (score === bestScore && best && ex.name.length < best.name.length)) {
      bestScore = score;
      best = ex;
    }
  }
  return bestScore >= 0.5 ? best : null;
}
